import {useCallback,useEffect,useMemo,useRef,useState,createContext,useContext,type FormEvent,type ReactNode,type MouseEvent} from 'react';
import {Link,NavLink,Route,Routes,useLocation,useNavigate,useParams} from 'react-router-dom';
import {ArrowLeft,ArrowRight,BadgePercent,Box,Check,ChevronRight,CircleHelp,ClipboardList,Crown,Gift,Heart,Home as HomeIcon,MapPin,Minus,Package,Plus,Search as SearchIcon,ShieldCheck,ShoppingBag,ShoppingCart,Sparkles,Star,Trash2,Truck,UserRound,X,Zap,Settings2,Ticket,LogOut,ChevronDown,Copy,Clock3,Flame,Layers3,UploadCloud} from 'lucide-react';
import {api,json} from './api';
import {type Product,type Me,type Cart,type Banner,type Category,type Order,type Coupon,type Variant,type Brand,price,statusTitle} from './types';

declare global {interface Window {Telegram?:{WebApp?:{initData:string;ready:()=>void;expand:()=>void;close:()=>void;HapticFeedback?:{impactOccurred:(v:string)=>void};setHeaderColor?:(s:string)=>void}}}}
const UserContext=createContext<{me:Me|null;brand:string;bonusPercent:number;checkoutEnabled:boolean;refreshMe:()=>Promise<void>;cartCount:number;refreshCart:()=>Promise<void>;notify:(s:string,type?:'error'|'ok')=>void}>({me:null,brand:'VAPORIA DISTRO',bonusPercent:5,checkoutEnabled:false,refreshMe:async()=>{},cartCount:0,refreshCart:async()=>{},notify:()=>{}});
const useStore=()=>useContext(UserContext);
function useFetch<T>(endpoint:string,deps:unknown[]=[]){const [data,setData]=useState<T|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{setData(await api<T>(endpoint));}catch(e){setError((e as Error).message);}finally{setLoading(false);}},[endpoint]);
  useEffect(()=>{void load();},[load,...deps]);return {data,setData,loading,error,reload:load};}
const notifyError=(err:unknown,notify:(s:string,t?:'error'|'ok')=>void)=>notify(err instanceof Error?err.message:'Сталася помилка','error');
const moneyInput=(p:number)=>String(p/100);
const kop=(s:string|number)=>Math.max(0,Math.round(Number(s||0)*100));

function Shell({children}:{children:ReactNode}){
 const loc=useLocation(),{brand,cartCount,me}=useStore();const navigate=useNavigate();
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[loc.pathname]);
 const tabs=[{path:'/',label:'Головна',icon:HomeIcon},{path:'/catalog',label:'Каталог',icon:Layers3},{path:'/search',label:'Пошук',icon:SearchIcon},{path:'/cart',label:'Кошик',icon:ShoppingCart},{path:'/profile',label:'Профіль',icon:UserRound}];
 return <div className="app-shell"><div className="ambient-glow"/>
 <header className="app-header"><button className="icon-btn back-btn" aria-label="Назад" onClick={()=>loc.pathname==='/'?window.Telegram?.WebApp?.close():navigate(-1)}><ArrowLeft size={21}/></button><Link to="/" className="header-brand"><span className="small-crown"><Crown size={13}/></span>{brand}</Link><div className="header-tools"><Link to="/favorites" aria-label="Обране"><Heart size={20}/></Link><Link to="/cart" aria-label="Кошик"><ShoppingBag size={19}/>{cartCount>0&&<i className="badge-count">{cartCount}</i>}</Link></div></header>
 <div className="app-body">{children}</div>
 <nav className="bottom-nav" aria-label="Головне меню">{tabs.map(t=><NavLink key={t.path} to={t.path} end={t.path==='/'} className={({isActive})=>`nav-tab ${isActive?'active':''}`}><span className="nav-icon"><t.icon size={21} strokeWidth={1.8}/>{t.path==='/cart'&&cartCount>0&&<span className="mini-dot">{cartCount}</span>}</span><span>{t.label}</span></NavLink>)}</nav>
 <div className="safe-footer"/></div>;
}
function PageTitle({children,subtitle}:{children:ReactNode;subtitle?:string}){return <div className="page-title"><h1>{children}</h1>{subtitle&&<p>{subtitle}</p>}</div>;}
function Loading(){return <div className="loading-block"><span className="spin"/> Завантаження...</div>;}
function Empty({icon=Package,title,subtitle,link,linkText}:{icon?:typeof Package;title:string;subtitle?:string;link?:string;linkText?:string}){const Icon=icon;return <div className="empty-state"><div className="empty-icon"><Icon size={34}/></div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}{link&&<Link to={link} className="button primary">{linkText||'До каталогу'} <ArrowRight size={16}/></Link>}</div>;}
function Art({product,className='',size='normal'}:{product?:Partial<Product>|{name:string;brand?:string;image_url?:string;slug?:string};className?:string;size?:string}){
 const [imageError,setImageError]=useState(false);
 useEffect(()=>setImageError(false),[product?.image_url]);
 const name=(product?.name||'VAPORIA').toUpperCase(),brand=product?.brand || (name.includes('VAPORESSO')?'VAPORESSO':name.split(' ')[0]);
 const hue=name.includes('HYPE')?'violet':name.includes('CHASER')?'lime':name.includes('VAPORESSO')?'cyan':name.includes('INBOTTLE')?'purple':'blue';
 return <div className={`product-art ${hue} ${size} ${className}`}>
 <div className="art-haze"/><div className="art-rays"/>
 {product?.image_url&&!imageError?<img className="real-product-img" src={product.image_url} alt={product.name||'Товар'} loading="lazy" onError={()=>setImageError(true)}/>:
 <div className="product-illustration"><div className="bottle-cap"/><div className="bottle-neck"/><div className="bottle-body"><span className="bottle-logo">{brand.slice(0,11)}</span><span className="bottle-name">{name.split(' ').slice(0,2).join(' ').slice(0,15)}</span><span className="bottle-footer">PREMIUM COLLECTION</span></div><div className="art-shadow"/></div>}
 <div className="art-spark">✦</div></div>;
}
function ProductCard({product,onChanged}:{product:Product;onChanged?:()=>void}){
 const {notify,refreshCart}=useStore(),[fav,setFav]=useState(false),[adding,setAdding]=useState(false);
 const add=async(e:MouseEvent)=>{e.preventDefault();e.stopPropagation();const v=product.variants.find(v=>v.is_active&&v.stock>0);if(!v)return notify('Товару немає в наявності','error');setAdding(true);try{await api('/cart',json('POST',{variant_id:v.id,quantity:1}));await refreshCart();notify('Додано до кошика');}catch(err){notifyError(err,notify);}finally{setAdding(false);}};
 const toggle=async(e:MouseEvent)=>{e.preventDefault();e.stopPropagation();try{const r=await api<{favorite:boolean}>(`/me/favorites/${product.id}`,json('POST'));setFav(r.favorite);onChanged?.();notify(r.favorite?'Додано в обране':'Прибрано з обраного');}catch(err){notifyError(err,notify);}};
 return <Link to={`/product/${product.slug}`} className="product-card"><div className="product-visual"><Art product={product}/>{product.badge&&<span className="product-label">{product.badge}</span>}<button className={`favorite-float ${fav?'is-fav':''}`} onClick={toggle} aria-label="В обране"><Heart size={17} fill={fav?'currentColor':'none'}/></button></div><div className="product-card-info"><span className="product-brand">{product.brand||'VAPORIA SELECTION'}</span><h3>{product.name}</h3><p>{product.subtitle}</p><div className="product-price"><div><strong>{price(product.base_price)}</strong>{product.compare_at_price&&<del>{price(product.compare_at_price)}</del>}</div><button onClick={add} disabled={adding||!product.variants.some(v=>v.stock>0)} aria-label="Додати в кошик"><ShoppingCart size={18}/></button></div></div></Link>;
}
const PRIMARY_CATEGORY_SLUGS=['pod-systemy','ridyny','kartrydzhi'];
function HeroCarousel({banners}:{banners:Banner[]}){
 const [active,setActive]=useState(0),touchX=useRef<number|null>(null);
 useEffect(()=>{setActive(i=>Math.min(i,Math.max(0,banners.length-1)));},[banners.length]);
 useEffect(()=>{if(banners.length<2)return;const timer=window.setInterval(()=>setActive(i=>(i+1)%banners.length),6500);return ()=>window.clearInterval(timer);},[banners.length]);
 if(!banners.length)return <Link to="/catalog" className="hero-carousel hero-fallback"><img src="/banners/main.webp" alt="VAPORIA DISTRO — головний банер"/></Link>;
 const change=(direction:number)=>setActive(i=>(i+direction+banners.length)%banners.length);
 const current=banners[active];
 return <section className="hero-carousel" aria-label="Акції та інформація магазину" onTouchStart={e=>{touchX.current=e.touches[0]?.clientX??null;}} onTouchEnd={e=>{if(touchX.current===null)return;const distance=e.changedTouches[0].clientX-touchX.current;if(Math.abs(distance)>38)change(distance>0?-1:1);touchX.current=null;}}>
 <Link key={current.id} className="carousel-banner-link" to={current.button_link||'/catalog'} aria-label={current.title}>
 {current.image_url?<img src={current.image_url} alt={current.title} className="carousel-banner-img"/>:<div className="carousel-text-slide"><span>{current.eyebrow}</span><strong>{current.title}</strong><small>{current.subtitle}</small></div>}</Link>
 {banners.length>1&&<><button type="button" className="carousel-control previous" onClick={()=>change(-1)} aria-label="Попередній банер"><ArrowLeft size={16}/></button><button type="button" className="carousel-control next" onClick={()=>change(1)} aria-label="Наступний банер"><ArrowRight size={16}/></button><div className="carousel-dots" aria-label="Слайди">{banners.map((b,i)=><button key={b.id} type="button" className={active===i?'current':''} onClick={()=>setActive(i)} aria-label={`Банер ${i+1}`}/>)}</div></>}
 </section>;
}
function Home(){
 const banners=useFetch<Banner[]>('/banners'),categories=useFetch<Category[]>('/categories'),brands=useFetch<Brand[]>('/brands'),products=useFetch<Product[]>('/products'),{me,bonusPercent}=useStore();
 const slides=(banners.data||[]).filter(b=>b.kind==='hero'),bonus=banners.data?.find(b=>b.kind==='bonus');
 const primary=PRIMARY_CATEGORY_SLUGS.map(slug=>(categories.data||[]).find(c=>c.slug===slug)).filter((c):c is Category=>Boolean(c));
 return <div className="home-page updated-home">
 <HeroCarousel banners={slides}/>
 <div className="trust-strip"><div><ShieldCheck size={18}/> Оригінальна<br/>продукція</div><div><Zap size={18}/> Швидке<br/>оформлення</div><div><Truck size={18}/> Доставка<br/>по Україні</div></div>
 <div className="section-heading"><div><span className="tiny-label">SHOP BY CATEGORY</span><h2>Категорії <em>товарів</em></h2></div><Link to="/catalog">Усі <ArrowRight size={16}/></Link></div>
 <div className="category-tiles three-main">{primary.map((c,i)=><Link to={`/catalog/${c.slug}`} className={`category-tile tile-${i} category-photo-tile`} key={c.id}>{c.image_url&&<div className="tile-photo" style={{backgroundImage:`linear-gradient(180deg,rgba(7,10,21,.1),rgba(7,10,21,.85)),url(${c.image_url})`}}/>}<div className="tile-icon">{i===0?<Zap/>:i===1?<Box/>:<Package/>}</div><b>{c.name}</b><ChevronRight size={16}/></Link>)}</div>
 <Link to={bonus?.button_link||'/bonuses'} className="bonus-banner">{bonus?.image_url&&<div className="banner-image-bg" style={{backgroundImage:`url(${bonus.image_url})`}}/>}<div className="bonus-orb"><Crown size={33}/></div><div><span>VAPORIA <b>CLUB</b> <Sparkles size={11}/></span><h3>{bonus?.title||'ТВОЇ ПОКУПКИ — ТВОЇ БОНУСИ'}</h3><p>{bonus?.subtitle||`Повертаємо ${bonusPercent}% бонусами`}</p><div className="bonus-link">ДЕТАЛЬНІШЕ <ArrowRight size={14}/></div></div></Link>
 <div className="section-heading"><div><span className="tiny-label">OUR BRANDS</span><h2>Наші <em>виробники</em></h2></div></div>
 {brands.loading?<Loading/>:<div className="brand-grid">{(brands.data||[]).map(b=><Link key={b.id} to={`/brand/${b.slug}`} className="brand-tile">{b.image_url?<img src={b.image_url} alt={b.name} loading="lazy"/>:<span className="brand-monogram">{b.name.split(' ').map(x=>x[0]).join('').slice(0,3)}</span>}<strong>{b.name}</strong><ChevronRight size={14}/></Link>)}</div>}
 <div className="section-heading"><div><span className="tiny-label">OUR FAVORITES</span><h2>Популярні <em>товари</em></h2></div><Link to="/catalog">Дивитись усі <ArrowRight size={16}/></Link></div>
 {products.loading?<Loading/>:<div className="product-grid">{(products.data||[]).slice(0,6).map(p=><ProductCard product={p} key={p.id}/>)}</div>}
 <div className="small-promo"><span><Gift size={24}/></span><div><b>Бонуси вже чекають!</b><p>{me?.bonus_balance||0} бонусів на вашому рахунку</p></div><Link to="/profile"><ArrowRight size={18}/></Link></div><div className="age-note">18+ • Інформація лише для повнолітніх. Дотримуйтеся місцевого законодавства.</div>
 </div>;
}
function Catalog(){const {data,loading}=useFetch<Category[]>('/categories');const visible=PRIMARY_CATEGORY_SLUGS.map(slug=>data?.find(c=>c.slug===slug)).filter((c):c is Category=>Boolean(c));return <div><PageTitle subtitle="Вибирайте свій напрям">Каталог</PageTitle>{loading?<Loading/>:<div className="catalog-list">{visible.map((c,i)=><Link to={`/catalog/${c.slug}`} className={`catalog-row catalog-${i%5}`} key={c.id}>{c.image_url&&<div className="catalog-image-bg" style={{backgroundImage:`url(${c.image_url})`}}/>}<div className="catalog-icon">{i===0?<Zap size={25}/>:i===1?<Box size={25}/>:i===2?<Package size={25}/>:i===3?<Star size={25}/>:<Crown size={25}/>}</div><div><b>{c.name}</b><span>{c.subtitle}</span></div><div className="catalog-arrow"><ChevronRight size={19}/></div></Link>)}</div>}</div>;}
function CategoryPage(){const {slug}=useParams(),{data,loading}=useFetch<Product[]>(`/products?category=${encodeURIComponent(slug||'')}`);const cats=useFetch<Category[]>('/categories');const category=cats.data?.find(c=>c.slug===slug);return <div><PageTitle subtitle={`${data?.length||0} товарів`}>{category?.name||'Товари'}</PageTitle>{loading?<Loading/>:data?.length?<div className="product-grid">{data.map(p=><ProductCard product={p} key={p.id}/>)}</div>:<Empty title="Наразі тут порожньо" link="/catalog"/>}</div>;}
function BrandPage(){const {slug}=useParams(),{data:brands}=useFetch<Brand[]>('/brands'),{data:products,loading}=useFetch<Product[]>(`/products?brand=${encodeURIComponent((brands?.find(b=>b.slug===slug)?.name)||'')}`);
 const current=brands?.find(b=>b.slug===slug);if(!brands)return <Loading/>;if(!current)return <Empty title="Виробника не знайдено" link="/" linkText="На головну"/>;return <div><PageTitle subtitle="Товари виробника">{current?.name||'Виробник'}</PageTitle>
 {current?.image_url&&<div className="brand-detail-hero"><img src={current.image_url} alt={current.name}/></div>}
 {loading?<Loading/>:products?.length?<div className="product-grid">{products.map(p=><ProductCard key={p.id} product={p}/>)}</div>:<Empty icon={Package} title="Поки немає товарів цього виробника" subtitle="Додайте товари з цією назвою бренду в адмінпанелі" link="/" linkText="На головну"/>}</div>;}
function ProductPage(){const {slug}=useParams(),{data:p,loading}=useFetch<Product>(`/products/${slug}`);const {notify,refreshCart}=useStore();const [variant,setVariant]=useState<number|null>(null),[qty,setQty]=useState(1),[selectedPhoto,setSelectedPhoto]=useState(''),[adding,setAdding]=useState(false),[fav,setFav]=useState(false);const navigate=useNavigate();
 useEffect(()=>{if(p){setVariant(p.variants[0]?.id||null);setSelectedPhoto(p.image_url||'');setQty(1);}},[p?.id]);
 const selected=p?.variants.find(v=>v.id===variant);const unit=selected?.price_override ?? p?.base_price ?? 0;const related=useFetch<Product[]>(`/products?category=${encodeURIComponent(p?.category_slug||'')}`);
 const add=async()=>{if(!selected)return;setAdding(true);try{await api('/cart',json('POST',{variant_id:selected.id,quantity:qty}));await refreshCart();notify('Товар додано до кошика');window.Telegram?.WebApp?.HapticFeedback?.impactOccurred('light');}catch(e){notifyError(e,notify);}finally{setAdding(false);}};
 const toggle=async()=>{if(!p)return;try{const r=await api<{favorite:boolean}>(`/me/favorites/${p.id}`,json('POST'));setFav(r.favorite);notify(r.favorite?'Додано в обране':'Прибрано з обраного');}catch(e){notifyError(e,notify);}};
 return <div className="product-page">{loading?<Loading/>:!p?<Empty title="Товар не знайдено" link="/catalog"/>:<>
 <div className="product-gallery"><div className="gallery-actions"><button onClick={()=>navigate(-1)}><ArrowLeft size={20}/></button><div><button aria-label="В обране" onClick={toggle}><Heart size={21} fill={fav?'currentColor':'none'}/></button><button aria-label="Поділитися" onClick={()=>{void navigator.clipboard?.writeText(location.href);notify('Посилання скопійовано');}}><UploadCloud size={20}/></button></div></div><Art product={{...p,image_url:selectedPhoto}} size="big"/>{p.badge&&<span className="gallery-badge">{p.badge}</span>}</div>
 <div className="photo-thumbs">{[p.image_url,...(p.gallery||[])].filter(Boolean).length?[p.image_url,...p.gallery].filter(Boolean).map((photo,i)=><button key={i} className={selectedPhoto===photo?'selected':''} onClick={()=>setSelectedPhoto(photo)}><img src={photo} alt={`Фото ${i+1}`}/></button>):<><div className="fake-thumb selected"><Zap size={20}/></div><div className="fake-thumb"><Crown size={20}/></div><div className="fake-thumb"><Sparkles size={20}/></div></>}</div>
 <div className="product-meta"><span className="eyebrow">{p.brand} / {p.category_name}</span><h1>{p.name}</h1><div className="rating-line"><Star size={14} fill="#ffc66b" color="#ffc66b"/><span>Варіанти на вибір</span><i/> <span>Наявність: {selected?.stock||0} шт.</span></div><div className="detail-price"><strong>{price(unit)}</strong>{p.compare_at_price&&<del>{price(p.compare_at_price)}</del>}</div></div>
 <div className="choices"><h3>Оберіть {p.category_slug==='pod-systemy'?'колір / комплектацію':'смак / варіант'}</h3><div className="variant-list">{p.variants.map(v=><button className={v.id===variant?'picked':''} disabled={!v.stock||!v.is_active} key={v.id} onClick={()=>{setVariant(v.id);setQty(1);}}>{v.label}{!v.stock&&<small>Немає</small>}</button>)}</div></div>
 <div className="qty-row"><div><b>Кількість</b><small>В наявності: {selected?.stock||0}</small></div><div className="stepper"><button disabled={qty<=1} onClick={()=>setQty(q=>Math.max(1,q-1))}><Minus size={16}/></button><strong>{qty}</strong><button disabled={qty>=(selected?.stock||0)} onClick={()=>setQty(q=>q+1)}><Plus size={16}/></button></div></div>
 <button className="button primary product-add" disabled={!selected?.stock||adding} onClick={()=>void add()}><ShoppingCart size={19}/> {adding?'ДОДАВАННЯ...':'ДОДАТИ В КОШИК'} <span>{price(unit*qty)}</span></button>
 <div className="product-description"><div className="description-title"><Sparkles size={18}/> Про товар</div><p>{p.description||p.subtitle}</p><div className="description-detail"><ShieldCheck size={18}/> Оригінальна продукція • Уточнюйте характеристики перед покупкою</div></div>
 {(related.data||[]).filter(item=>item.id!==p.id).length>0&&<><div className="section-heading related-head"><h2>Може <em>зацікавити</em></h2></div><div className="product-grid">{related.data!.filter(item=>item.id!==p.id).slice(0,4).map(item=><ProductCard key={item.id} product={item}/>)}</div></>}
 </>}</div>;
}
function SearchPage(){const [q,setQ]=useState(''),[debounced,setDebounced]=useState('');useEffect(()=>{const t=setTimeout(()=>setDebounced(q.trim()),250);return()=>clearTimeout(t);},[q]);const {data,loading}=useFetch<Product[]>(`/products?search=${encodeURIComponent(debounced)}`);const chips=['INBOTTLE','HYPE','VAPORESSO','CHASER','POD','Картриджі','Blue razz','Lemon'];return <div><PageTitle subtitle="Знайди те, що подобається">Пошук</PageTitle><div className="search-box"><SearchIcon size={21}/><input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Товари, бренди, смаки..."/>{q&&<button onClick={()=>setQ('')}><X size={18}/></button>}</div><div className="search-suggestions"><h3>{q?'Результати пошуку':'Популярні запити'}</h3>{!q&&<div className="search-chips">{chips.map(c=><button key={c} onClick={()=>setQ(c)}>{c} <ArrowRight size={12}/></button>)}</div>}</div>{loading?<Loading/>:data?.length?<div className="product-grid search-results">{data.map(p=><ProductCard product={p} key={p.id}/>)}</div>:<Empty icon={SearchIcon} title="Нічого не знайдено" subtitle="Спробуйте іншу назву або бренд"/>}</div>;}
function CartPage(){const {notify,refreshCart,me,checkoutEnabled}=useStore();const {data,loading,reload}=useFetch<Cart>('/cart'),[promo,setPromo]=useState(sessionStorage.getItem('vaporia_promo')||''),[discount,setDiscount]=useState(0);const navigate=useNavigate();
 const change=async(id:string,quantity:number)=>{try{await api(`/cart/${id}`,json('PATCH',{quantity}));await Promise.all([reload(),refreshCart()]);}catch(e){notifyError(e,notify);}};
 const apply=async()=>{if(!promo.trim()){setDiscount(0);sessionStorage.removeItem('vaporia_promo');return;}try{const r=await api<{discount:number}>('/coupon/check',json('POST',{code:promo,subtotal:data?.subtotal||0}));setDiscount(r.discount);sessionStorage.setItem('vaporia_promo',promo.trim().toUpperCase());notify('Промокод застосовано');}catch(e){setDiscount(0);notifyError(e,notify);}};
 useEffect(()=>{setDiscount(0);},[data?.subtotal]);
 return <div><PageTitle subtitle={`${data?.items.length||0} позицій`}>Кошик</PageTitle>{loading?<Loading/>:!data?.items.length?<Empty icon={ShoppingCart} title="Тут поки порожньо" subtitle="Час знайти щось цікаве!" link="/catalog" linkText="ПЕРЕЙТИ ДО КАТАЛОГУ"/>:<><div className="cart-list">{data.items.map(item=><div className="cart-item" key={item.id}><Link to={`/product/${item.slug}`}><Art product={{name:item.name,image_url:item.image_url}}/></Link><div className="cart-item-main"><b>{item.name}</b><p>{item.variant_label}</p><strong>{price(item.unit_price*item.quantity)}</strong><div className="cart-stepper"><div className="stepper"><button onClick={()=>void change(item.id,item.quantity-1)}><Minus size={14}/></button><span>{item.quantity}</span><button disabled={item.quantity>=item.stock} onClick={()=>void change(item.id,item.quantity+1)}><Plus size={14}/></button></div><button className="trash-btn" aria-label="Видалити" onClick={()=>void change(item.id,0)}><Trash2 size={17}/></button></div></div></div>)}</div>
 <div className="panel promo-panel"><h3><Ticket size={17}/> Промокод</h3><div className="promo-input"><input placeholder="Введіть промокод" value={promo} onChange={e=>setPromo(e.target.value)} /><button onClick={()=>void apply()}><ArrowRight size={19}/></button></div></div>
 <div className="panel totals-panel"><div><span>Вартість товарів</span><b>{price(data.subtotal)}</b></div><div><span>Знижка</span><b className="accent-discount">−{price(discount)}</b></div><div><span>Ваші бонуси</span><b>{me?.bonus_balance||0} <Crown size={13}/></b></div><div className="total-final"><span>До оплати</span><strong>{price(data.subtotal-discount)}</strong></div><small>* Доставку перевізника оплачують окремо, якщо вона передбачена.</small></div>
 <button disabled={!checkoutEnabled} className="button primary full-width checkout-link" onClick={()=>navigate('/checkout')}><ShoppingBag size={20}/> {checkoutEnabled?'ОФОРМИТИ ЗАМОВЛЕННЯ':'ОФОРМЛЕННЯ ПОКИ НЕДОСТУПНЕ'} <ArrowRight size={17}/></button>{!checkoutEnabled&&<p className="checkout-warning">Оформлення тимчасово закрите, доки продавець не налаштує юридичні вимоги й перевірку повноліття.</p>}
 </>}</div>;
}
function CheckoutPage(){const {data,loading}=useFetch<Cart>('/cart'),{me,refreshMe,refreshCart,notify,checkoutEnabled}=useStore(),navigate=useNavigate();const [name,setName]=useState(''),[phone,setPhone]=useState(''),[city,setCity]=useState(''),[details,setDetails]=useState(''),[delivery,setDelivery]=useState<'nova_poshta'|'pickup'>('nova_poshta'),[payment,setPayment]=useState<'cod'|'manager'>('cod'),[comment,setComment]=useState(''),[promo,setPromo]=useState(sessionStorage.getItem('vaporia_promo')||''),[discount,setDiscount]=useState(0),[bonus,setBonus]=useState(0),[agreed,setAgreed]=useState(false),[submitting,setSubmitting]=useState(false);const requestId=useRef(crypto.randomUUID());
 useEffect(()=>{if(me?.first_name)setName(me.first_name);},[me?.first_name]);
 useEffect(()=>{if(promo&&data?.subtotal){api<{discount:number}>('/coupon/check',json('POST',{code:promo,subtotal:data.subtotal})).then(r=>setDiscount(r.discount)).catch(()=>{setPromo('');setDiscount(0);});}},[data?.subtotal]);
 const allowed=Math.min(me?.bonus_balance||0,Math.floor(Math.max(0,(data?.subtotal||0)-discount)*0.3/100));
 const finalTotal=Math.max(0,(data?.subtotal||0)-discount-bonus*100);
 const submit=async(e:FormEvent)=>{e.preventDefault();if(!data?.items.length)return;setSubmitting(true);try{const r=await api<{order:{id:string;number:string}}>('/checkout',json('POST',{request_id:requestId.current,customer_name:name,phone,delivery_method:delivery,city,shipping_details:delivery==='pickup'?'Самовивіз':details,payment_method:payment,comment,coupon_code:promo,bonus_used:bonus,age_agreed:agreed}));sessionStorage.removeItem('vaporia_promo');await Promise.all([refreshCart(),refreshMe()]);navigate(`/order-success/${r.order.number}`,{replace:true});}catch(err){notifyError(err,notify);}finally{setSubmitting(false);}};
 if(!checkoutEnabled)return <Empty icon={ShieldCheck} title="Оформлення тимчасово закрите" subtitle="Адміністратор має налаштувати правові вимоги та перевірку повноліття" link="/cart" linkText="Повернутись у кошик"/>;if(loading)return <Loading/>;if(!data?.items.length)return <Empty title="Спочатку додайте товар" link="/catalog"/>;
 return <div><PageTitle subtitle="Залишився лише один крок">Оформлення</PageTitle><form onSubmit={e=>void submit(e)} className="checkout-form"><section className="panel checkout-panel"><h3><UserRound size={20}/> Контактні дані</h3><label>Ваше ім’я<input required minLength={2} maxLength={90} value={name} onChange={e=>setName(e.target.value)} placeholder="Ім’я та прізвище"/></label><label>Номер телефону<input required type="tel" pattern="[+0-9 ()-]{9,22}" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+380XXXXXXXXX"/></label></section>
 <section className="panel checkout-panel"><h3><Truck size={20}/> Доставка</h3><div className="segmented"><button type="button" className={delivery==='nova_poshta'?'chosen':''} onClick={()=>setDelivery('nova_poshta')}>Нова пошта</button><button type="button" className={delivery==='pickup'?'chosen':''} onClick={()=>setDelivery('pickup')}>Самовивіз</button></div><label>Місто<input required value={city} onChange={e=>setCity(e.target.value)} placeholder="Назва міста" maxLength={100}/></label>{delivery==='nova_poshta'&&<label>Відділення / поштомат<input required value={details} onChange={e=>setDetails(e.target.value)} placeholder="№ відділення або адреса" maxLength={200}/></label>}</section>
 <section className="panel checkout-panel"><h3><ShoppingBag size={20}/> Оплата</h3><div className="payment-options"><label><input type="radio" checked={payment==='cod'} onChange={()=>setPayment('cod')}/> При отриманні (за домовленістю)</label><label><input type="radio" checked={payment==='manager'} onChange={()=>setPayment('manager')}/> Узгодити з менеджером</label></div><small>Онлайн-еквайринг поки не підключено. Менеджер підтвердить доступний спосіб оплати.</small></section>
 <section className="panel checkout-panel"><h3><Crown size={20}/> Бонуси та промокод</h3><div className="mini-promo"><input placeholder="Промокод" value={promo} onChange={e=>setPromo(e.target.value.toUpperCase())}/><button type="button" onClick={async()=>{try{const r=await api<{discount:number}>('/coupon/check',json('POST',{code:promo,subtotal:data.subtotal}));setDiscount(r.discount);setBonus(0);notify('Промокод діє');}catch(e){setDiscount(0);notifyError(e,notify);}}}>Застосувати</button></div><div className="bonus-checkbox"><div><b>Списати бонуси</b><small>Доступно {me?.bonus_balance||0}; максимум {allowed} бонусів (30%)</small></div><input type="number" min={0} max={allowed} value={bonus} onChange={e=>setBonus(Math.min(allowed,Math.max(0,Math.floor(Number(e.target.value)||0))))}/></div></section>
 <section className="panel checkout-panel"><label>Коментар до замовлення<textarea rows={3} maxLength={800} value={comment} onChange={e=>setComment(e.target.value)} placeholder="За бажанням"/></label></section>
 <div className="panel totals-panel"><div><span>Товари</span><b>{price(data.subtotal)}</b></div><div><span>Знижка / бонуси</span><b>−{price(discount+bonus*100)}</b></div><div className="total-final"><span>До оплати</span><strong>{price(finalTotal)}</strong></div></div>
 {me && !me.age_verified && <div className="panel admin-info">Для реального продажу адміністратор повинен перевірити документ, що підтверджує вік, та дозволити оформлення. У деморежимі перевірка може бути вимкнена.</div>}<label className="accept-check"><input type="checkbox" required checked={agreed} onChange={e=>setAgreed(e.target.checked)}/><span>Підтверджую, що мені виповнилося 18 років, дані замовлення правильні та розумію, що менеджер має підтвердити доступність товарів і порядок доставки. Під час видачі може знадобитися документ.</span></label><button className="button primary full-width" type="submit" disabled={!agreed||submitting}>{submitting?'ВІДПРАВЛЯЄМО...':'ПІДТВЕРДИТИ ЗАМОВЛЕННЯ'} <ArrowRight size={17}/></button>
 </form></div>;
}
