function BonusHistory(){const {data,loading}=useFetch<{id:string;delta:number;description:string;created_at:string}[]>('/me/bonuses'),{me,bonusPercent}=useStore();return <div><PageTitle subtitle="Нарахування та списання">Мої бонуси</PageTitle><div className="bonus-balance large"><span><Crown size={21}/> VAPORIA CLUB</span><strong>{me?.bonus_balance||0} <small>БОНУСІВ</small></strong><p>{bonusPercent}% від виконаних замовлень • 1 бонус = 1 ₴ • списання до 30% суми</p></div>{loading?<Loading/>:(data||[]).length?<div className="history-list">{data!.map(r=><div className="history-row" key={r.id}><div><b>{r.description}</b><small>{new Date(r.created_at).toLocaleString('uk-UA')}</small></div><strong className={r.delta>=0?'positive':'negative'}>{r.delta>0?'+':''}{r.delta}</strong></div>)}</div>:<Empty icon={Crown} title="Історії поки немає" subtitle="За завершені замовлення нараховуються бонуси"/>}</div>;}
function Orders(){const {data,loading}=useFetch<Order[]>('/me/orders');return <div><PageTitle subtitle="Стежте за своїми покупками">Історія замовлень</PageTitle>{loading?<Loading/>:data?.length?<div className="orders-list">{data.map(o=><div className="panel order-card" key={o.id}><div className="order-head"><div><span className="eyebrow">ЗАМОВЛЕННЯ</span><h3>№{o.number}</h3></div><span className={`status status-${o.status}`}>{statusTitle[o.status]}</span></div><small>{new Date(o.created_at).toLocaleString('uk-UA')}</small><div className="order-items">{o.items.map((item,i)=><p key={i}>{item.product_name} <span>×{item.quantity}</span><br/><small>{item.variant_label}</small></p>)}</div><div className="order-foot"><span>До оплати</span><strong>{price(o.total)}</strong></div>{o.bonus_awarded>0&&<div className="order-bonus"><Crown size={14}/> Нараховано {o.bonus_awarded} бонусів</div>}</div>)}</div>:<Empty icon={ClipboardList} title="Замовлень ще немає" link="/catalog"/>}</div>;}
function Profile(){const {me,bonusPercent}=useStore();return <div><PageTitle subtitle="Ваш особистий простір">Профіль</PageTitle><div className="profile-user"><img src={me?.photo_url||'/brand-logo.png'} alt="Аватар"/><div><span>ПРИВІТ,</span><h2>{me?.first_name||'Клієнт VAPORIA'} <Sparkles size={16}/></h2><p>@{me?.username||'vaporia_member'}</p></div><Crown size={24}/></div><Link to="/bonuses" className="bonus-balance"><div className="balance-top"><span><Crown size={22}/> VAPORIA CLUB</span><ChevronRight size={18}/></div><span className="balance-caption">ВАШ БАЛАНС БОНУСІВ</span><strong>{me?.bonus_balance||0} <small>БОНУСІВ</small></strong><p>Отримуйте {bonusPercent}% після виконаного замовлення</p><div className="balance-spark">✦</div></Link><div className="profile-menu"><Link to="/orders"><span className="profile-icon"><ClipboardList size={20}/></span><span>Історія замовлень<small>Ваші замовлення та їхній статус</small></span><ChevronRight/></Link><Link to="/favorites"><span className="profile-icon"><Heart size={20}/></span><span>Обране<small>Збережені товари</small></span><ChevronRight/></Link><Link to="/bonuses"><span className="profile-icon"><Gift size={20}/></span><span>Мої бонуси<small>Історія нарахувань і списань</small></span><ChevronRight/></Link>{me?.role==='admin'&&<Link to="/admin"><span className="profile-icon"><Settings2 size={20}/></span><span>Адмінпанель<small>Товари, замовлення, банери</small></span><ChevronRight/></Link>}</div><div className="profile-bottom"><ShieldCheck size={18}/> VAPORIA DISTRO • PREMIUM STORE • 18+</div></div>;}
async function uploadMedia(file:File):Promise<string>{
 if(!['image/jpeg','image/png','image/webp','image/heic','image/heif'].includes(file.type) && !/\.hei[cf]$/i.test(file.name))throw new Error('Виберіть фото JPG, PNG, WEBP або HEIC');
 if(file.size>16*1024*1024)throw new Error('Фото завелике (макс. 16 МБ до стиснення)');
 let body:Blob=file;
 // Resize larger smartphone photos to web-friendly dimensions before upload.
 if(file.size>3.8*1024*1024 || !['image/png','image/jpeg','image/webp'].includes(file.type)){
  const img=await createImageBitmap(file).catch(()=>{throw new Error('Цей HEIC не вдалося перетворити. Збережіть фото у JPG або PNG.');});const ratio=Math.min(1,1600/Math.max(img.width,img.height));
  const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));
  canvas.getContext('2d')?.drawImage(img,0,0,canvas.width,canvas.height);img.close();
  body=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(v=>v?resolve(v):reject(new Error('Не вдалося підготувати фото')),'image/webp',0.82));
 }
 if(body.size>4*1024*1024)throw new Error('Фото перевищує 4 МБ. Зменште його розмір.');
 const response=await fetch('/api/admin/media',{method:'POST',headers:{'X-Vaporia-App':'1','Content-Type':body.type},credentials:'same-origin',body});
 const result=await response.json().catch(()=>({error:'Помилка завантаження'}));
 if(!response.ok)throw new Error(result.error||'Не вдалося завантажити фото');
 return String(result.url);
}
function PhotoField({name='image_url',label,initial='',notify}:{name?:string;label:string;initial?:string;notify:(message:string,type?:'ok'|'error')=>void}){
 const [url,setUrl]=useState(initial),[uploading,setUploading]=useState(false);
 return <div className="photo-admin-field"><label>{label}<input name={name} value={url} maxLength={600} onChange={e=>setUrl(e.target.value)} placeholder="Завантажте фото або вставте HTTPS URL"/></label>
 <div className="photo-input-row"><label className="photo-upload-btn"><UploadCloud size={17}/>{uploading?'Завантаження...':'Завантажити фото'}<input disabled={uploading} type="file" accept="image/png,image/jpeg,image/webp,image/heic,image/heif" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;setUploading(true);try{const address=await uploadMedia(file);setUrl(address);notify('Фото додано до PostgreSQL');}catch(error){notifyError(error,notify);}finally{setUploading(false);e.target.value='';}}}/></label>
 {url&&<img className="photo-preview" src={url} alt="Попередній перегляд" onError={e=>{e.currentTarget.style.opacity='.3';}}/>}</div><small>JPG / PNG / WEBP до 4 МБ; фотографія зберігається у PostgreSQL. Після завантаження натисніть «Зберегти» у формі.</small></div>;
}
function GalleryPhotosField({initial='',notify}:{initial?:string;notify:(message:string,type?:'ok'|'error')=>void}){
 const [urls,setUrls]=useState(initial),[busy,setBusy]=useState(false);
 return <div className="photo-admin-field"><label>Галерея — по одному фото / URL на рядок<textarea rows={3} name="gallery" value={urls} onChange={e=>setUrls(e.target.value)}/></label>
 <label className="photo-upload-btn"><UploadCloud size={17}/>{busy?'Завантаження...':'Додати фото до галереї'}<input type="file" multiple accept="image/png,image/jpeg,image/webp,image/heic,image/heif" disabled={busy} onChange={async e=>{const files=Array.from(e.target.files||[]).slice(0,12);setBusy(true);try{for(const file of files){const address=await uploadMedia(file);setUrls(old=>old.trim()?old.trim()+'\n'+address:address);}notify(`${files.length} фото додано до галереї`);}catch(err){notifyError(err,notify);}finally{setBusy(false);e.target.value='';}}}/></label></div>;
}
function Admin(){const {notify,brand}=useStore();const [tab,setTab]=useState<'overview'|'orders'|'products'|'categories'|'brands'|'banners'|'coupons'|'bonus'>('overview'),[rev,setRev]=useState(0);const [picked,setPicked]=useState<any>(null);const [newMode,setNewMode]=useState(false);const refresh=()=>{setRev(v=>v+1);setPicked(null);setNewMode(false);};
 const [brands,setBrands]=useState<Brand[]>([]);const [overview,setOverview]=useState<any>(null),[orders,setOrders]=useState<Order[]>([]),[products,setProducts]=useState<Product[]>([]),[categories,setCategories]=useState<Category[]>([]),[banners,setBanners]=useState<Banner[]>([]),[coupons,setCoupons]=useState<Coupon[]>([]);
 useEffect(()=>{const doFetch=async()=>{try{const [a,b,c,d,e,f,g]=await Promise.all([api('/admin/overview'),api<Order[]>('/admin/orders'),api<Product[]>('/admin/products'),api<Category[]>('/admin/categories'),api<Banner[]>('/admin/banners'),api<Coupon[]>('/admin/coupons'),api<Brand[]>('/admin/brands')]);setBrands(g);setOverview(a);setOrders(b);setProducts(c);setCategories(d);setBanners(e);setCoupons(f);}catch(err){notifyError(err,notify);}};void doFetch();},[rev]);
 const updateStatus=async(o:Order,status:string)=>{if(!confirm(`Перевести замовлення №${o.number} у статус «${statusTitle[status]}»?`))return;try{await api(`/admin/orders/${o.id}/status`,json('PATCH',{status}));notify('Статус збережено');refresh();}catch(e){notifyError(e,notify);}};
 const saveCategory=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const body={slug:String(d.slug),name:String(d.name),subtitle:String(d.subtitle),icon:String(d.icon),image_url:String(d.image_url),sort_order:Number(d.sort_order),is_active:d.is_active==='on'};await api(`/admin/categories${picked?.id?'/'+picked.id:''}`,json(picked?.id?'PATCH':'POST',body));notify('Категорію збережено');refresh();}catch(e){notifyError(e,notify);}};
 const saveBrand=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const body={slug:String(d.slug),name:String(d.name),image_url:String(d.image_url),sort_order:Number(d.sort_order),is_active:d.is_active==='on'};await api(`/admin/brands${picked?.id?'/'+picked.id:''}`,json(picked?.id?'PATCH':'POST',body));notify('Виробника збережено');refresh();}catch(err){notifyError(err,notify);}};
 const saveBanner=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const body={eyebrow:String(d.eyebrow),title:String(d.title),subtitle:String(d.subtitle),image_url:String(d.image_url),button_text:String(d.button_text),button_link:String(d.button_link),kind:String(d.kind),sort_order:Number(d.sort_order),is_active:d.is_active==='on'};await api(`/admin/banners${picked?.id?'/'+picked.id:''}`,json(picked?.id?'PATCH':'POST',body));notify('Банер збережено');refresh();}catch(e){notifyError(e,notify);}};
 const saveCoupon=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const body={code:String(d.code),kind:String(d.kind),value:String(d.kind)==='fixed'?kop(String(d.value)):Number(d.value),min_subtotal:kop(String(d.min_subtotal)),max_uses:d.max_uses?Number(d.max_uses):null,is_active:d.is_active==='on'};await api(`/admin/coupons${picked?.id?'/'+picked.id:''}`,json(picked?.id?'PATCH':'POST',body));notify('Промокод збережено');refresh();}catch(e){notifyError(e,notify);}};
 const saveProduct=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{
   const slug=String(d.slug);const old=(picked?.variants||[]) as Variant[];
   const variantText=String(d.variants||'').split('\n').map(s=>s.trim()).filter(Boolean);
   const variants=variantText.map((line,i)=>{const [label,skuRaw,stockRaw,overrideRaw]=line.split('|').map(s=>s.trim());const sku=skuRaw||`${slug}-${i+1}`;const existing=old.find(v=>v.sku===sku);return {...(existing?.id?{id:existing.id}:{}),label,sku,stock:Math.max(0,Number(stockRaw||0)),price_override:overrideRaw?kop(overrideRaw):null,is_active:true};});
   const body={category_id:Number(d.category_id),slug,name:String(d.name),brand:String(d.brand),subtitle:String(d.subtitle),description:String(d.description),image_url:String(d.image_url),gallery:String(d.gallery||'').split('\n').map(s=>s.trim()).filter(Boolean),base_price:kop(String(d.base_price)),compare_at_price:d.compare_at_price?kop(String(d.compare_at_price)):null,badge:String(d.badge),is_active:d.is_active==='on',variants};
   await api(`/admin/products${picked?.id?'/'+picked.id:''}`,json(picked?.id?'PATCH':'POST',body));notify('Товар збережено');refresh();
 }catch(err){notifyError(err,notify);}};
 const start=(item:any=null)=>{setPicked(item);setNewMode(!item);window.scrollTo({top:120,behavior:'smooth'});};
 const inputs=(keys:{name:string;label:string;type?:string;defaultValue?:string|number;placeholder?:string;required?:boolean}[])=>keys.map(k=>k.name==='image_url'?<PhotoField key={k.name} label={k.label} initial={String(k.defaultValue??'')} notify={notify}/>:<label key={k.name}>{k.label}<input name={k.name} type={k.type||'text'} step={k.type==='number'&&(['base_price','compare_at_price','value','min_subtotal'].includes(k.name))?'0.01':undefined} required={k.required} defaultValue={k.defaultValue??''} placeholder={k.placeholder}/></label>);
 return <div className="admin-page"><div className="admin-header"><span className="eyebrow">VAPORIA CONTROL CENTER</span><h1>Адмін<em>панель</em></h1><p>Керуйте каталогом, замовленнями та бонусами</p></div>
 <div className="admin-tabs">{([{id:'overview',label:'Огляд'},{id:'orders',label:'Замовлення'},{id:'products',label:'Товари'},{id:'categories',label:'Категорії'},{id:'brands',label:'Виробники'},{id:'banners',label:'Банери'},{id:'coupons',label:'Промокоди'},{id:'bonus',label:'Бонуси'}] as const).map(t=><button key={t.id} className={tab===t.id?'active':''} onClick={()=>{setTab(t.id);setPicked(null);setNewMode(false);}}>{t.label}</button>)}</div>
 {tab==='overview'&&<><div className="admin-stat-grid">{[{label:'Замовлень',v:overview?.orders||0,icon:ShoppingBag},{label:'Очікують',v:overview?.pending||0,icon:Clock3},{label:'Товарів',v:overview?.products||0,icon:Package},{label:'Клієнтів',v:overview?.customers||0,icon:UserRound}].map(s=><div key={s.label} className="admin-stat"><s.icon size={20}/><strong>{s.v}</strong><span>{s.label}</span></div>)}</div><div className="panel admin-info"><h3>Виконані замовлення</h3><div className="admin-revenue">{price(overview?.revenue||0)}</div><p>Сума замовлень у статусі «Виконано» (не банківська звітність).</p></div><div className="admin-info panel"><b>Важливо</b><p>Демонстраційні товари мають тестові залишки. Перед запуском перевірте ціни, склад, фото, описи, реквізити та умови продажу. Нові замовлення спершу отримують статус «Очікує».</p></div></>}
 {tab==='orders'&&<div className="admin-orders"><h2>Замовлення <span>{orders.length}</span></h2>{orders.map(o=><div className="panel admin-order" key={o.id}><div className="order-head"><h3>№{o.number}</h3><span className={`status status-${o.status}`}>{statusTitle[o.status]}</span></div><div className="admin-order-meta"><div><b>{o.customer_name}</b><a href={`tel:${o.phone}`}>{o.phone}</a></div><strong>{price(o.total)}</strong></div><p>@{o.username||o.telegram_id} · {new Date(o.created_at).toLocaleString('uk-UA')}</p><p>{o.delivery_method==='pickup'?'Самовивіз':'Нова пошта'}: {o.city}, {o.shipping_details}</p><p>Оплата: {o.payment_method==='cod'?'При отриманні':'Узгодити з менеджером'}</p>{o.comment&&<p>Коментар: {o.comment}</p>}<div className="admin-lineitems">{o.items.map((i,index)=><div key={index}>{i.product_name} / {i.variant_label} ×{i.quantity}</div>)}</div>{o.status!=='completed'&&o.status!=='cancelled'&&<div className="status-actions">{(o.status==='pending'?['confirmed','cancelled']:o.status==='confirmed'?['shipped','completed','cancelled']:['completed','cancelled']).map(s=><button key={s} onClick={()=>void updateStatus(o,s)} className={s==='cancelled'?'danger':''}>{statusTitle[s]}</button>)}</div>}</div>)}{!orders.length&&<Empty title="Замовлень поки немає"/>}</div>}
 {tab==='products'&&<><div className="admin-list-header"><h2>Товари ({products.length})</h2><button className="button secondary" onClick={()=>start()}>+ Додати</button></div>{(picked||newMode)&&<form key={picked?.id||'new-product'} onSubmit={e=>void saveProduct(e)} className="panel admin-form"><h3>{picked?.id?'Редагувати товар':'Новий товар'}</h3><label>Категорія<select name="category_id" defaultValue={picked?.category_id||categories[0]?.id}>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>{inputs([{name:'name',label:'Назва *',defaultValue:picked?.name,required:true},{name:'slug',label:'Slug (латиниця через дефіс) *',defaultValue:picked?.slug,required:true},{name:'brand',label:'Бренд',defaultValue:picked?.brand},{name:'subtitle',label:'Короткий підзаголовок',defaultValue:picked?.subtitle},{name:'base_price',label:'Ціна, ₴',type:'number',defaultValue:moneyInput(picked?.base_price||0),required:true},{name:'compare_at_price',label:'Стара ціна, ₴',type:'number',defaultValue:picked?.compare_at_price?moneyInput(picked.compare_at_price):''},{name:'badge',label:'Позначка (ХІТ, АКЦІЯ)',defaultValue:picked?.badge},{name:'image_url',label:'Фото HTTPS URL',defaultValue:picked?.image_url}])}<label>Опис<textarea rows={4} name="description" defaultValue={picked?.description||''}/></label><GalleryPhotosField key={picked?.id||'new-gallery'} initial={(picked?.gallery||[]).join('\n')} notify={notify}/><label>Варіанти: назва | SKU | залишок | ціна ₴ (необов'язково)<textarea rows={5} required name="variants" defaultValue={(picked?.variants||[]).filter((v:Variant)=>v.is_active).map((v:Variant)=>`${v.label} | ${v.sku} | ${v.stock} | ${v.price_override?moneyInput(v.price_override):''}`).join('\n')} placeholder={'Lemon Lime | inbottle-lemon | 20 |\nCherry | inbottle-cherry | 15 | 355'}/></label><label className="checkbox-label"><input type="checkbox" name="is_active" defaultChecked={picked?.is_active??true}/> Активний товар</label><div className="form-actions"><button className="button primary" type="submit">Зберегти</button><button className="button secondary" type="button" onClick={()=>{setPicked(null);setNewMode(false);}}>Скасувати</button></div></form>}
 <div className="admin-records">{products.map(p=><button className={`admin-record ${picked?.id===p.id?'selected':''}`} key={p.id} onClick={()=>start(p)}><Art product={p}/><span><b>{p.name}</b><small>{price(p.base_price)} • {p.variants.reduce((sum,v)=>sum+v.stock,0)} шт. • {p.is_active?'Активний':'Прихований'}</small></span><ChevronRight size={16}/></button>)}</div></>}
 {tab==='categories'&&<><div className="admin-list-header"><h2>Категорії</h2><button className="button secondary" onClick={()=>start()}>+ Додати</button></div>{(picked||newMode)&&<form key={picked?.id||'new-cat'} onSubmit={e=>void saveCategory(e)} className="panel admin-form">{inputs([{name:'name',label:'Назва',required:true,defaultValue:picked?.name},{name:'slug',label:'Slug',required:true,defaultValue:picked?.slug},{name:'subtitle',label:'Підзаголовок',defaultValue:picked?.subtitle},{name:'icon',label:'Іконка',defaultValue:picked?.icon||'box'},{name:'image_url',label:'Фонове фото URL',defaultValue:picked?.image_url},{name:'sort_order',label:'Порядок',type:'number',defaultValue:picked?.sort_order??0}])}<label className="checkbox-label"><input name="is_active" type="checkbox" defaultChecked={picked?.is_active??true}/> Активна</label><button className="button primary">Зберегти</button></form>}{categories.map(c=><button key={c.id} className="admin-record simple" onClick={()=>start(c)}><b>{c.name}</b><small>{c.slug} • {c.is_active?'Активна':'Прихована'}</small><ChevronRight size={16}/></button>)}</>}
 {tab==='brands'&&<><div className="admin-list-header"><h2>Виробники ({brands.length})</h2><button className="button secondary" onClick={()=>start()}>+ Додати</button></div>
 {(picked||newMode)&&<form key={picked?.id||'new-brand'} onSubmit={e=>void saveBrand(e)} className="panel admin-form"><h3>{picked?.id?'Редагувати виробника':'Новий виробник'}</h3>{inputs([{name:'name',label:'Назва виробника',required:true,defaultValue:picked?.name},{name:'slug',label:'Slug (латиниця через дефіс)',required:true,defaultValue:picked?.slug},{name:'image_url',label:'Логотип або фото виробника',defaultValue:picked?.image_url},{name:'sort_order',label:'Порядок',type:'number',defaultValue:picked?.sort_order??brands.length+1}])}<label className="checkbox-label"><input type="checkbox" name="is_active" defaultChecked={picked?.is_active??true}/> Активний</label><button className="button primary">Зберегти виробника</button></form>}
 {brands.map(b=><button key={b.id} className="admin-record simple admin-brand-row" onClick={()=>start(b)}>{b.image_url&&<img src={b.image_url} alt=""/>}<b>{b.name}</b><small>{b.slug} • {b.is_active?'Активний':'Прихований'}</small><ChevronRight size={16}/></button>)}</>}
 {tab==='banners'&&<><div className="admin-list-header"><h2>Банери</h2><button className="button secondary" onClick={()=>start()}>+ Додати</button></div>{(picked||newMode)&&<form key={picked?.id||'new-banner'} onSubmit={e=>void saveBanner(e)} className="panel admin-form">{inputs([{name:'eyebrow',label:'Мітка',defaultValue:picked?.eyebrow},{name:'title',label:'Заголовок',defaultValue:picked?.title,required:true},{name:'subtitle',label:'Опис',defaultValue:picked?.subtitle},{name:'image_url',label:'Фон URL (необов’язково)',defaultValue:picked?.image_url},{name:'button_text',label:'Текст кнопки',defaultValue:picked?.button_text||'Дивитися'},{name:'button_link',label:'Посилання (/catalog)',defaultValue:picked?.button_link||'/catalog'},{name:'sort_order',label:'Порядок',type:'number',defaultValue:picked?.sort_order||0}])}<label>Тип<select name="kind" defaultValue={picked?.kind||'promo'}><option value="hero">Головний</option><option value="bonus">Бонуси</option><option value="promo">Промо</option></select></label><label className="checkbox-label"><input type="checkbox" name="is_active" defaultChecked={picked?.is_active??true}/> Активний</label><button className="button primary">Зберегти</button></form>}{banners.map(b=><button key={b.id} className="admin-record simple" onClick={()=>start(b)}><b>{b.title}</b><small>{b.kind} • {b.is_active?'Активний':'Прихований'}</small><ChevronRight size={16}/></button>)}</>}
 {tab==='coupons'&&<><div className="admin-list-header"><h2>Промокоди</h2><button className="button secondary" onClick={()=>start()}>+ Додати</button></div>{(picked||newMode)&&<form key={picked?.id||'new-coupon'} onSubmit={e=>void saveCoupon(e)} className="panel admin-form">{inputs([{name:'code',label:'Код',defaultValue:picked?.code,required:true},{name:'value',label:'Значення (% або ₴)',type:'number',defaultValue:picked?(picked.kind==='fixed'?moneyInput(picked.value):picked.value):5,required:true},{name:'min_subtotal',label:'Мінімальна сума ₴',type:'number',defaultValue:picked?moneyInput(picked.min_subtotal):0},{name:'max_uses',label:'Ліміт використань (порожньо — без ліміту)',type:'number',defaultValue:picked?.max_uses??''}])}<label>Тип знижки<select name="kind" defaultValue={picked?.kind||'percent'}><option value="percent">Відсотки (%)</option><option value="fixed">Сума (₴)</option></select></label><label className="checkbox-label"><input type="checkbox" name="is_active" defaultChecked={picked?.is_active??true}/> Активний</label><button className="button primary">Зберегти</button></form>}{coupons.map(c=><button key={c.id} className="admin-record simple" onClick={()=>start(c)}><b>{c.code} — {c.kind==='percent'?c.value+'%':price(c.value)}</b><small>{c.uses} використань • {c.is_active?'Активний':'Вимкнений'}</small><ChevronRight size={16}/></button>)}</>}
 {tab==='bonus'&&<><h2>Перевірка віку клієнта</h2><div className="panel admin-info"><p>Підтверджуйте вік лише після перевірки документа або уповноваженим провайдером. Це ручний запис факту перевірки, а не автоматична ідентифікація.</p></div><form className="panel admin-form" onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));void api('/admin/age/verify',json('POST',{telegram_id:d.telegram_id,verified:d.verified==='true'})).then(()=>{notify('Статус перевірки віку оновлено');(e.target as HTMLFormElement).reset();}).catch(err=>notifyError(err,notify));}}><label>Telegram ID клієнта<input required name="telegram_id" pattern="[0-9]+" placeholder="123456789"/></label><label>Рішення<select name="verified" defaultValue="true"><option value="true">Вік перевірено</option><option value="false">Зняти підтвердження</option></select></label><button className="button primary">Зберегти статус</button></form><h2>Ручне коригування бонусів</h2><div className="panel admin-info"><p>Потрібен числовий Telegram ID клієнта. Зміни записуються в історію бонусів. Введіть від’ємне число, щоб списати.</p></div><form className="panel admin-form" onSubmit={e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));void api('/admin/bonuses/adjust',json('POST',{telegram_id:d.telegram_id,delta:Number(d.delta),description:d.description})).then(()=>{notify('Бонуси змінено');(e.target as HTMLFormElement).reset();}).catch(err=>notifyError(err,notify));}}>{inputs([{name:'telegram_id',label:'Telegram ID клієнта',required:true},{name:'delta',label:'Зміна бонусів (+/-)',type:'number',required:true},{name:'description',label:'Причина',required:true}])}<button className="button primary">Підтвердити зміну</button></form></>}
 </div>;
}
function AgeGate({brand,onConfirm}:{brand:string;onConfirm:()=>Promise<void>}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <div className="age-overlay"><div className="age-dialog"><img src="/brand-logo.png" alt="Логотип"/><span className="age-badge">18+</span><span className="eyebrow">AGE VERIFICATION</span><h1>ДОСТУП ТІЛЬКИ<br/><em>ДЛЯ ПОВНОЛІТНІХ</em></h1><p>У магазині {brand} представлені товари з віковими обмеженнями. Для продовження підтвердьте, що вам виповнилося 18 років.</p>{error&&<div className="form-error">{error}</div>}<button disabled={busy} className="button primary full-width" onClick={()=>{setBusy(true);void onConfirm().catch(e=>setError((e as Error).message)).finally(()=>setBusy(false));}}>МЕНІ Є 18 РОКІВ <Check size={17}/></button><button className="button ghost full-width" onClick={()=>window.Telegram?.WebApp?.close()}>Покинути магазин</button><small>Самодекларація не замінює перевірку віку під час продажу або видачі.</small></div></div>;}
function App(){const [me,setMe]=useState<Me|null>(null),[brand,setBrand]=useState('VAPORIA DISTRO'),[bonusPercent,setPercent]=useState(5),[checkoutEnabled,setCheckoutEnabled]=useState(false),[cartCount,setCartCount]=useState(0),[ready,setReady]=useState(false),[authError,setAuthError]=useState(''),[toast,setToast]=useState<{msg:string;type:'error'|'ok'}|null>(null);
 const toastTimeout=useRef<number>();const notify=useCallback((msg:string,type:'error'|'ok'='ok')=>{setToast({msg,type});clearTimeout(toastTimeout.current);toastTimeout.current=window.setTimeout(()=>setToast(null),3300);},[]);
 const refreshMe=useCallback(async()=>{const u=await api<Me>('/me');setMe(u);},[]);
 const refreshCart=useCallback(async()=>{try{const cart=await api<Cart>('/cart');setCartCount(cart.items.reduce((s,i)=>s+i.quantity,0));}catch{setCartCount(0);}},[]);
 useEffect(()=>{const init=async()=>{try{
  const tg=window.Telegram?.WebApp;
  tg?.ready();tg?.expand();try{tg?.setHeaderColor?.('#080c17');}catch{}
  const settings=await api<{brand:string;bonusPercent:number;devAuth:boolean;checkoutEnabled:boolean}>('/config');setBrand(settings.brand);setPercent(settings.bonusPercent);setCheckoutEnabled(settings.checkoutEnabled);
  // Existing cookie is valid if /me succeeds. Telegram auth happens only when needed.
  try{await refreshMe();}catch{
    if(tg?.initData){await api('/auth/telegram',json('POST',{initData:tg.initData}));await refreshMe();}
    else if(settings.devAuth){await api('/auth/dev',json('POST',{}));await refreshMe();}
    else throw new Error('Відкрийте цей магазин через кнопку бота в Telegram.');
  }
  await refreshCart();
 }catch(e){setAuthError((e as Error).message);}finally{setReady(true);}};void init();},[refreshCart,refreshMe]);
 if(!ready)return <div className="startup"><div className="spin"/><h2>VAPORIA <span>DISTRO</span></h2><p>Готуємо магазин...</p></div>;
 if(authError)return <div className="startup"><img src="/brand-logo.png" alt="Логотип"/><h2>VAPORIA DISTRO</h2><p>{authError}</p><button className="button secondary" onClick={()=>location.reload()}>Спробувати ще раз</button></div>;
 const confirmAge=async()=>{await api('/me/confirm-age',json('POST',{}));await refreshMe();};
 return <UserContext.Provider value={{me,brand,bonusPercent,checkoutEnabled,refreshMe,cartCount,refreshCart,notify}}><Shell><Routes><Route path="/" element={<Home/>}/><Route path="/catalog" element={<Catalog/>}/><Route path="/catalog/:slug" element={<CategoryPage/>}/><Route path="/brand/:slug" element={<BrandPage/>}/><Route path="/product/:slug" element={<ProductPage/>}/><Route path="/search" element={<SearchPage/>}/><Route path="/cart" element={<CartPage/>}/><Route path="/checkout" element={<CheckoutPage/>}/><Route path="/order-success/:number" element={<OrderSuccess/>}/><Route path="/profile" element={<Profile/>}/><Route path="/favorites" element={<Favorites/>}/><Route path="/orders" element={<Orders/>}/><Route path="/bonuses" element={<BonusHistory/>}/><Route path="/admin" element={me?.role==='admin'?<Admin/>:<Empty icon={ShieldCheck} title="Немає доступу" link="/"/>}/><Route path="*" element={<Empty title="Сторінку не знайдено" link="/"/>}/></Routes></Shell>{me&&!me.age_confirmed&&<AgeGate brand={brand} onConfirm={confirmAge}/>} {toast&&<div className={`toast ${toast.type}`}><span>{toast.type==='error'?<CircleHelp size={18}/>:<Check size={18}/>}</span>{toast.msg}</div>}</UserContext.Provider>;
}
export default App;
